mapper.select:
select g.id as id, g.user_id as userId, u.username as username, u.avatar as avatar, g.story_title as storyTitle, g.story_summary as storySummary, p.company_name as companyName, p.position_name as positionName, p.city as city, date_format(p.entry_time, '%Y-%m-%d %H:%i:%s') as entryTime, date_format(g.published_time, '%Y-%m-%d %H:%i:%s') as publishedTime from osh_internal_member_growth_story g inner join osh_user u on u.id = g.user_id and u.delete_flag = 0 and u.status = 0 inner join osh_internal_member_employment_profile p on p.user_id = g.user_id and p.delete_flag = 0 and (p.job_status = 2 or p.entry_time is not null) and p.resume_file_key is not null and p.resume_file_key != '' and p.offer_file_key is not null and p.offer_file_key != '' where g.delete_flag = 0 and g.is_public = 1 and g.user_id != #{excludeUserId}
and ( u.username like concat('%', #{keyword}, '%') or g.story_title like concat('%', #{keyword}, '%') or g.story_summary like concat('%', #{keyword}, '%') or p.company_name like concat('%', #{keyword}, '%') or p.position_name like concat('%', #{keyword}, '%') )
order by g.published_time desc, g.id desc
